        "No document type": "Gan chineál doiciméid",
        "No document types are offered here yet. An administrator adds them under Document types in the settings.": "Níl aon chineál doiciméid ar fáil anseo fós. Cuireann riarthóir iad leis faoi Cineálacha doiciméad sna socruithe.",
        "No document types yet. Add one to give the files on meetings and agenda items their own fields.": "Níl aon chineál doiciméid ann fós. Cuir ceann leis chun a réimsí féin a thabhairt do chomhaid cruinnithe agus míreanna clár oibre.",
        "No documents of this type yet.": "Níl aon doiciméad den chineál seo fós.",
        "No files attached yet.": "Níl aon chomhad ceangailte fós.",
        "Offered on": "Ar fáil ar",
        "Offered when a clerk picks a type for a document.": "Ar fáil nuair a roghnaíonn cléireach cineál do dhoiciméad.",
        "Save details": "Sábháil sonraí",
        "The Nextcloud file these details describe. One record per file.": "An comhad Nextcloud a chuireann na sonraí seo síos air. Taifead amháin in aghaidh an chomhaid.",
        "The agenda item the file is attached to.": "An mhír ar an gclár oibre a bhfuil an comhad ceangailte léi.",
        "The details could not be saved.": "Níorbh fhéidir na sonraí a shábháil.",
        "The document type as a clerk picks it, such as Raadsvoorstel.": "An cineál doiciméid mar a roghnaíonn cléireach é, mar shampla Raadsvoorstel.",
        "The extra fields a document of this kind carries.": "Na réimsí breise atá ag doiciméad den chineál seo.",
        "The files of this page could not be read.": "Níorbh fhéidir comhaid an leathanaigh seo a léamh.",
        "The kind of document, which decides the extra fields.": "Cineál an doiciméid, a shocraíonn na réimsí breise.",
        "The meeting the file is attached to.": "An cruinniú a bhfuil an comhad ceangailte leis.",
        "The name this field's value is stored under on every document of this kind. Choose it once and leave it alone: renaming it here does not move the values already recorded, so the old ones become unreachable.": "An t-ainm faoina stóráiltear luach an réimse seo ar gach doiciméad den chineál seo. Roghnaigh uair amháin é agus fág mar atá: má athainmnítear anseo é, ní bhogtar na luachanna atá taifeadta cheana, agus ní féidir teacht ar na seanchinn.",
        "The values of the fields the document type declares.": "Luachanna na réimsí a fhógraíonn an cineál doiciméid.",
        "Tick this to make the field compulsory: the details of a document of this kind cannot be saved while it is left empty.": "Cuir tic anseo chun an réimse a dhéanamh éigeantach: ní féidir sonraí doiciméid den chineál seo a shábháil fad is atá sé folamh.",
        "What documents of this kind are.": "Cad is doiciméid den chineál seo ann.",
        "What the field is called on screen: the caption above the input when someone fills in a document's details.": "Cad a thugtar ar an réimse ar an scáileán: an lipéad os cionn an ionchuir nuair a líonann duine sonraí doiciméid.",
        "Where the type is offered: files of a meeting, files of an agenda item, or both.": "Cá háit a bhfuil an cineál ar fáil: comhaid cruinnithe, comhaid míre clár oibre, nó an dá cheann.",
        "A kind of document with the extra fields its details carry.": "Cineál doiciméid leis na réimsí breise atá ina shonraí.",
        "Conversion needs filinq": "Teastaíonn filinq don tiontú",
        "Convert Word, Excel and PowerPoint papers to PDF when they are added": "Tiontaigh páipéir Word, Excel agus PowerPoint go PDF nuair a chuirtear leis iad",
        "Install and enable filinq to convert papers. Until then, papers stay as they were added.": "Suiteáil agus cumasaigh filinq chun páipéir a thiontú. Go dtí sin, fanann páipéir mar a cuireadh leis iad.",
        "Members read the PDF of each Word, Excel or PowerPoint paper. The original stays next to it for the secretariat.": "Léann baill PDF gach páipéir Word, Excel nó PowerPoint. Fanann an bunleagan in aice leis don rúnaíocht.",
        "No Office papers on this page.": "Níl aon pháipéir Office ar an leathanach seo.",
        "Not converted: {reason}": "Níor tiontaíodh: {reason}",
        "Office papers as PDF": "Páipéir Office mar PDF",
