        "Link case": "Nasc cás",
        "Link the case system in integriq, on the Case system connection. Griffiers can then fetch case documents onto agenda items and send the meeting file after the minutes are approved.": "Nasc an córas cásbhainistíochta in integriq, ar an gceangal Córas cásbhainistíochta. Ansin is féidir le griffier doiciméid cháis a fháil ar mhíreanna clár oibre agus comhad an chruinnithe a sheoladh nuair a formheastar na miontuairiscí.",
        "No case system is connected.": "Níl aon chóras cásbhainistíochta ceangailte.",
