        "Fetch brings documents from the case system onto an agenda item; send takes documents to a case.": "Tugann faighte doiciméid ón gcóras cásbhainistíochta ar mhír chlár oibre; tugann seoladh doiciméid chuig cás.",
        "One line per document, each with its own status.": "Líne amháin in aghaidh an doiciméid, agus a stádas féin ag gach ceann.",
