        "The Nextcloud file, when the document is one.": "An comhad Nextcloud, nuair is comhad é an doiciméad.",
        "The account that fetched or sent, or system when minutes approval sent it.": "An cuntas a fuair nó a sheol, nó an córas nuair a sheol formheas na miontuairiscí é.",
        "The address of the case in the case system.": "Seoladh an cháis sa chóras cásbhainistíochta.",
        "The address of the case the documents came from or went to.": "Seoladh an cháis as ar tháinig na doiciméid nó ar chuaigh siad chuige.",
        "The agenda item the documents were fetched onto or whose decisions were sent.": "An mhír chlár oibre ar faightear na doiciméid uirthi nó ar seoladh a cinntí.",
        "The case number or title, as shown on screen.": "Uimhir nó teideal an cháis, mar a thaispeántar ar an scáileán é.",
        "The case number, such as Z-2026-00412.": "Uimhir an cháis, mar shampla Z-2026-00412.",
        "The case this agenda item belongs to in the organisation's case system: its address, its case number and its title. Set by linking the item to a case; decidiq reads the case once to fill the title.": "An cás lena mbaineann an mhír chlár oibre seo i gcóras cásbhainistíochta na heagraíochta: a seoladh, a uimhir agus a teideal. Socraítear é trí mhír a nascadh le cás; léann decidiq an cás uair amháin chun an teideal a líonadh.",
        "The confidentiality ground it was sent with.": "An bunús rúndachta lenar seoladh é.",
        "The document was sent marked confidential.": "Seoladh an doiciméad marcáilte mar rúnda.",
        "The document's address in the case system, once it is there.": "Seoladh an doiciméid sa chóras cásbhainistíochta, nuair atá sé ann.",
        "The document's file name.": "Ainm comhaid an doiciméid.",
        "The meeting whose file was sent, or whose agenda item documents were fetched for.": "An cruinniú ar seoladh a chomhad nó ar faightear doiciméid dá mhíreanna clár oibre.",
        "The title of the case as the case system names it.": "Teideal an cháis mar a ainmníonn an córas cásbhainistíochta é.",
        "What the document is: the agenda, an item document, a decision, the decision list, the minutes or the proof package.": "Cad é an doiciméad: an clár oibre, doiciméad míre, cinneadh, an liosta cinntí, na miontuairiscí nó an pacáiste fianaise.",
        "When the fetch or send was asked for.": "Cathain a iarradh an fháil nó an seoladh.",
        "Where decidiq finds the document again when it is sent a second time.": "An áit a bhfaigheann decidiq an doiciméad arís nuair a sheoltar an dara huair é.",
        "Why the case system refused the document.": "Cén fáth ar dhiúltaigh an córas cásbhainistíochta an doiciméad.",
        "Rights per record type": "Cearta de réir cineál taifid",
        "The rules below decide who may read and change each kind of record. They name decidiq roles. Add your own groups to a role and they get the same rights; the role's own group keeps them too.": "Socraíonn na rialacha thíos cé a fhéadfaidh gach cineál taifid a léamh agus a athrú. Ainmníonn siad róil decidiq. Cuir do ghrúpaí féin le ról agus gheobhaidh siad na cearta céanna; coinníonn grúpa an róil féin iad freisin.",
