        "Hear of new and changed agendas, papers, decisions and minutes of the bodies you follow, straight away or as a daily or weekly digest.": "Faigh scéala faoi chláir oibre, páipéir, cinntí agus miontuairiscí nua agus athraithe de na comhlachtaí a leanann tú, láithreach nó mar achoimre laethúil nó seachtainiúil.",
