        "The Nextcloud account of the member who subscribes. Empty for a resident.": "Cuntas Nextcloud an bhaill a liostálann. Folamh do chónaitheoir.",
        "Resident": "Cónaitheoir",
        "The portal subject reference of the resident who subscribes. Empty for a member. decidiq never stores a resident's email address.": "Tagairt tairsí an chónaitheora a liostálann. Folamh do bhall. Ní stórálann decidiq seoladh ríomhphoist cónaitheora riamh.",
        "The bodies to follow. Empty means every body.": "Na comhlachtaí le leanúint. Ciallaíonn folamh gach comhlacht.",
        "What to follow": "Cad atá le leanúint",
        "Agendas, papers, decisions and minutes, one or more.": "Cláir oibre, páipéir, cinntí agus miontuairiscí, ceann amháin nó níos mó.",
        "Immediately (after a short wait that groups an editing session), a daily digest at 07:00, or a weekly digest on Monday at 07:00.": "Láithreach (tar éis fanacht gearr a ghrúpálann seisiún eagarthóireachta), achoimre laethúil ag 07:00, nó seachtainiúil Dé Luain ag 07:00.",
