        "The meeting it belongs to, when there is one.": "An cruinniú lena mbaineann sé, má tá ceann ann.",
        "The schema of the object the event is about, such as meeting, agenda-item or decision.": "Scéimre an oibiachta a bhfuil an t-imeacht faoi, mar meeting, agenda-item nó decision.",
        "Object": "Oibiacht",
        "The object the event is about. The digest checks the subscriber may read it before sending.": "An oibiacht a bhfuil an t-imeacht faoi. Seiceálann an achoimre gur féidir leis an síntiúsóir í a léamh roimh sheoladh.",
        "The meeting, paper, decision or minutes title.": "Teideal an chruinnithe, an pháipéir, an chinnidh nó na miontuairiscí.",
        "Summary": "Achoimre",
