        "Whether residents may hear of it: only publicly published agendas, decisions and minutes count.": "Cibé an féidir le cónaitheoirí cloisteáil faoi: ní áirítear ach cláir oibre, cinntí agus miontuairiscí a foilsíodh go poiblí.",
