        "An existing person with this email will be reused; otherwise a new one is created.": "Úsáidfear duine atá ann cheana leis an ríomhphost seo arís; mura bhfuil, cruthófar duine nua.",
        "An opaque identifier for the respondent, used when answers are anonymous or the respondent is not a recorded person.": "Aitheantóir teimhneach don fhreagróir, a úsáidtear nuair a bhíonn freagraí gan ainm nó nuair nach duine taifeadta é an freagróir.",
        "Ancillary positions intake": "Glacadh isteach post coimhdeach",
        "And after. The pair is the record REQ-DWP-002 asks for: a step whose outcome changed without an action to point at is a step nobody can explain.": "Agus ina dhiaidh. Is é an péire an taifead a iarrann REQ-DWP-002: is céim nach féidir le duine ar bith a mhíniú í céim ar athraigh a toradh gan gníomh le pointeáil air.",
