        "Configure, per governance body, where adopted decisions, public agendas, and approved minutes are published. Anonymous read access is served exclusively through OpenCatalogi / OpenRegister — never an app-local public page.": "Cumraigh, in aghaidh an chomhlachta rialachais, cá bhfoilsítear cinntí glactha, cláir oibre phoiblí agus miontuairiscí formheasta. Ní sholáthraítear rochtain léite gan ainm ach trí OpenCatalogi / OpenRegister, riamh trí leathanach poiblí áitiúil na haipe.",
