        "Controls mode-specific labels across the app — for example what a governance body is called. Default: government.": "Rialaíonn sé lipéid a bhaineann le modh ar fud na haipe, mar shampla cad a thugtar ar chomhlacht rialachais. Réamhshocrú: rialtas.",
