        "Convocation sent at": "Comóradh seolta ag",
        "Copied from the step at instantiation so the stage can resolve its own actor when it becomes live. The rule lives on the stage and not only on the route because editing a route must never change a stage already in flight (REQ-AR-012).": "Cóipeáilte ón gcéim ag cur ar bun ionas gur féidir leis an stáitse a ghníomhaí féin a réiteach nuair a éiríonn sé beo. Tá an riail ar an stáitse agus ní ar an mbealach amháin toisc nár cheart go n-athródh eagarthóireacht bealaigh stáitse atá ar siúl cheana riamh (REQ-AR-012).",
        "Copied from the step at instantiation, so editing a route never changes what the silence of a stage already in flight means.": "Cóipeáilte ón gcéim ag cur ar bun, ionas nach n-athraíonn eagarthóireacht bealaigh riamh an bhrí atá le tost stáitse atá ar siúl cheana.",
        "Corporate (corp)": "Corparáideach (corp)",
        "Corporate-governance extension (beyond Popolo, MCCG): board-member independence, mode=corp. NOT the same question as `external`, which records whether the member sits from outside the administrative organ. A member can be external and non-independent, or internal and independent; neither value is derivable from the other.": "Síneadh rialachais chorparáidigh (thar Popolo, MCCG): neamhspleáchas ball boird, mode=corp. NÍ hionann é agus an cheist `external`, a thaifeadann an suíonn an ball ó lasmuigh den orgán riaracháin. Is féidir le ball a bheith seachtrach agus neamh-neamhspleách, nó inmheánach agus neamhspleách; ní féidir ceachtar luach a dhíorthú ón gceann eile.",
        "Could not approve the reaction": "Níorbh fhéidir an t-imoibriú a fhormheas",
