        "Date after which this type may no longer be used. Empty means indefinitely.": "Dáta nach féidir an cineál seo a úsáid ina dhiaidh. Ciallaíonn folamh go héiginnte.",
        "Date from which this type may be used.": "Dáta ar féidir an cineál seo a úsáid uaidh.",
        "Date the membership ends. The end-membership step sets Membership.endDate to this value.": "Dáta a chríochnaíonn an bhallraíocht. Socraíonn an chéim chríochnaithe ballraíochta Membership.endDate don luach seo.",
        "Date the person was formally installed. Completing the installation step requires this, installationType and installationMeeting.": "Dáta a insealbhaíodh an duine go foirmiúil. Chun an chéim insealbhaithe a chríochnú, teastaíonn sé seo, installationType agus installationMeeting.",
        "Days after approval": "Laethanta tar éis formheasa",
        "De datum waarop het besluit is gepubliceerd. Onderscheiden van `publishedAt`, dat het moment van publiceren in dit systeem vastlegt; dit is de datum die het besluit zelf draagt. BRC `publicatiedatum`.": "An dáta ar foilsíodh an cinneadh. Difriúil ó `publishedAt`, a thaifeadann an nóiméad foilsithe sa chóras seo; seo an dáta atá ar an gcinneadh féin. BRC `publicatiedatum`.",
        "De datum waarop het besluit is verzonden aan de belanghebbende. BRC `verzenddatum`.": "An dáta ar seoladh an cinneadh chuig an bpáirtí leasmhar. BRC `verzenddatum`.",
        "De datum waarop het besluit vervalt. Onderscheiden van `effectiveDate`, die zegt wanneer het ingaat. BRC `vervaldatum`.": "An dáta a dtéann an cinneadh as feidhm. Difriúil ó `effectiveDate`, a deir cathain a thagann sé i bhfeidhm. BRC `vervaldatum`.",
        "Deadline reminder sent at": "Meabhrúchán spriocdháta seolta ag",
