        "Decision list": "Liosta cinntí",
        "Decision maker": "Cinnteoir",
        "Decision outcome recorded when status=decided. Null when status is pending/active/skipped. `returned` is the sign-off case and behaves unlike the rest: it re-opens an EARLIER stage rather than ending this one, which is why `rejected` and `deferred` could not express it, both end a stage and neither reopens one.": "Toradh an chinnidh a thaifeadtar nuair is status=decided é. Null nuair is pending/active/skipped é an stádas. Is é `returned` cás an tsínithe agus iompraíonn sé difriúil ón gcuid eile: athosclaíonn sé stáitse NÍOS LUAITHE seachas an ceann seo a chríochnú, agus sin an fáth nach bhféadfadh `rejected` ná `deferred` é a chur in iúl, críochnaíonn an dá cheann stáitse agus ní athosclaíonn ceachtar acu ceann.",
