        "Nextcloud user id linked to the person by the account-linking step. Optional until linked; the induction-pack step depends on it.": "Aitheantas úsáideora Nextcloud nasctha leis an duine ag an gcéim nasctha cuntas. Roghnach go dtí go nasctar é; braitheann céim an phacáiste ionduchtaithe air.",
