        "No agenda item types configured yet. An example set seeds some, or add your own.": "Gan cineálacha míre cláir oibre cumraithe fós. Cuireann tacar samplach roinnt acu ar fáil, nó cuir do chuid féin leis.",
        "No agenda items use this kind yet.": "Níl aon mhíreanna cláir oibre ag úsáid an chineáil seo fós.",
        "No answer within the term": "Gan freagra laistigh den téarma",
        "No audio files found in this meeting's folder. Upload a recording to the meeting folder, then refresh.": "Níor aimsíodh aon chomhaid fuaime i bhfillteán an chruinnithe seo. Uaslódáil taifeadadh chuig fillteán an chruinnithe, ansin athnuaigh.",
        "No body compositions configured yet.": "Gan comhdhéanaimh chomhlachta cumraithe fós.",
