        "No meeting linked — the voting round cannot be opened": "Gan cruinniú nasctha: ní féidir an babhta vótála a oscailt",
        "No meeting types configured yet. An example set seeds some, or add your own.": "Gan cineálacha cruinnithe cumraithe fós. Cuireann tacar samplach roinnt acu ar fáil, nó cuir do chuid féin leis.",
