        "No remuneration recorded for this year, or none you can read.": "Níl aon luach saothair taifeadta don bhliain seo, nó níl aon cheann ar féidir leat a léamh.",
        "No remuneration recorded, or none you can read.": "Níl aon luach saothair taifeadta, nó níl aon cheann ar féidir leat a léamh.",
        "No responses recorded yet.": "Gan freagraí taifeadta fós.",
        "No responses were recorded for this decision.": "Níor taifeadadh aon fhreagraí don chinneadh seo.",
