        "No self-evaluation cycles yet for this body.": "Gan timthriallta féinmheasúnaithe don chomhlacht seo fós.",
        "No sign-off route on this object yet.": "Gan bealach sínithe ar an réad seo fós.",
        "No speech-to-text provider is installed on this instance. You can still attach a recording and record consent; transcription becomes available once a provider (e.g. a local Whisper app) is installed.": "Níl aon soláthraí urlabhra go téacs suiteáilte ar an gcás seo. Is féidir leat taifeadadh a cheangal agus toiliú a thaifeadadh fós; beidh trascríobh ar fáil nuair a shuiteáiltear soláthraí (m.sh. aip áitiúil Whisper).",
        "No staged route configured": "Gan bealach céimnithe cumraithe",
