        "Nobody is recorded as your substitute, so this sign-off is still waiting on you. Its deadline has not moved.": "Níl duine ar bith taifeadta mar d'ionadaí, mar sin tá an síniú seo fós ag fanacht ort. Níor bhog a spriocdháta.",
