        "Reference to the Meeting where the person was installed. The meeting itself is owned elsewhere and only linked here.": "Tagairt don chruinniú inar insealbhaíodh an duine. Is in áit eile atá an cruinniú féin faoi úinéireacht agus níl sé ach nasctha anseo.",
        "Reference to the Membership created as an outcome. Optional until created: an intake often onboards a person before the membership row exists.": "Tagairt don bhallraíocht a cruthaíodh mar thoradh. Roghnach go dtí go gcruthaítear í: is minic a ionduchtaíonn glacadh isteach duine sula mbíonn an tsraith ballraíochta ann.",
        "Reference to the Membership to be end-dated. Required. End-dating happens on the end-membership step, never as an automatic side effect.": "Tagairt don bhallraíocht a bhfuil dáta deiridh le cur léi. Riachtanach. Tarlaíonn an dáta deiridh ar an gcéim chríochnaithe ballraíochta, riamh mar fhoiriarmhairt uathoibríoch.",
        "Reference to the governance body the person is joining. Required. With targetRole it derives the body-role group mapping the assign-groups step uses.": "Tagairt don chomhlacht rialachais a bhfuil an duine ag dul isteach ann. Riachtanach. In éineacht le targetRole díorthaíonn sé an mapáil grúpa comhlacht-róil a úsáideann an chéim sannta grúpaí.",
        "Reference to the governance body the person is leaving. Required. With the person's role it derives the body-role group mapping the revoke-groups step uses.": "Tagairt don chomhlacht rialachais atá an duine ag fágáil. Riachtanach. In éineacht le ról an duine díorthaíonn sé an mapáil grúpa comhlacht-róil a úsáideann an chéim cúlghairme grúpaí.",
