        "You are voting on behalf of: {name}": "Tá tú ag vótáil thar ceann: {name}",
        "You have been asked to stand in on a sign-off that is part-way through its term. Whoever acts first closes it.": "Iarradh ort seasamh isteach ar shíniú atá leath bealaigh trína théarma. Dúnann cibé duine a ghníomhaíonn ar dtús é.",
        "You may sign for {actor} under a mandate.": "Is féidir leat síniú do {actor} faoi shainordú.",
        "Your reaction": "D'imoibriú",
        "Your reaction was submitted for moderation": "Cuireadh d'imoibriú isteach le haghaidh modhnóireachta",
        "Your response is anonymous. It cannot be traced back to you, even by an administrator.": "Tá do fhreagra gan ainm. Ní féidir é a rianú siar chugat, fiú ag riarthóir.",
        "Your sign-off has moved up": "Bogadh do shíniú suas",
        "Your stand-in has been asked as well": "Iarradh ar d'ionadaí freisin",
        "Your vote has been recorded.": "Taifeadadh do vóta.",
        "Your vote was recorded": "Taifeadadh do vóta",
