        "consultationType=tender: public tender reference/notice number.": "consultationType=tender: tagairt/uimhir fógra an tairisceana phoiblí.",
        "consultationType=tender: the winning party recorded when the award decision is made (status=awarded). Decidiq owns publish/manage/award only; authoring is procest and bidding is pipelinq.": "consultationType=tender: an páirtí a bhuaigh, taifeadta nuair a dhéantar an cinneadh dámhachtana (status=awarded). Níl ag Decidiq ach foilsiú/bainistiú/dámhachtain; is le procest an t-údarú agus is le pipelinq an tairiscint.",
