        "{n} already on Deck": "{n} ar Deck cheana",
        "{n} card(s) created": "{n} cárta cruthaithe",
        "{n} item(s) could not be projected.": "Níorbh fhéidir {n} mhír a theilgean.",
        "{n} open action items": "{n} mhír ghníomhaíochta oscailte",
        "{responded} of {invited} responded": "D'fhreagair {responded} de {invited}",
        "{verb} by {actor}": "{verb} ag {actor}",
        "{verb} by {actor}, on behalf of {onBehalfOf}": "{verb} ag {actor}, thar ceann {onBehalfOf}",
        "A summary of one paper, or a comparison of two.": "Achoimre ar pháipéar amháin, nó comparáid idir dhá cheann.",
        "Checked at": "Seiceáilte ag",
        "Checked by": "Seiceáilte ag",
        "Compared with": "I gcomparáid le",
        "Compared with (title)": "I gcomparáid le (teideal)",
        "Failure": "Teip",
        "Paper": "Páipéar",
        "Paper summary": "Achoimre ar pháipéar",
        "Paper title": "Teideal an pháipéir",
        "Summarised in parts": "Achoimrithe ina chodanna",
        "The AI output in markdown, then the clerk's edit of it.": "Aschur IS i markdown, ansin eagarthóireacht an chléirigh air.",
        "The Nextcloud file id of the paper (schema:isBasedOn).": "Aitheantas comhaid Nextcloud an pháipéir (schema:isBasedOn).",
        "The Nextcloud file id of the second paper of a comparison.": "Aitheantas comhaid Nextcloud an dara páipéar i gcomparáid.",
        "The TaskProcessing provider that wrote the text, for provenance.": "An soláthraí TaskProcessing a scríobh an téacs, le haghaidh bunáite.",
        "The TaskProcessing task that writes the text.": "An cúram TaskProcessing a scríobhann an téacs.",
        "The agenda item the paper is attached to.": "An mhír chlár oibre a bhfuil an páipéar ceangailte léi.",
        "The display name of the clerk who last showed or hid the summary, as the label shows it.": "Ainm taispeána an chléirigh a thaispeáin nó a d'fholaigh an achoimre go deireanach, mar a thaispeánann an lipéad é.",
        "The file name of the paper when the summary was asked for.": "Ainm comhaid an pháipéir nuair a iarradh an achoimre.",
        "The file name of the second paper of a comparison.": "Ainm comhaid an dara páipéar i gcomparáid.",
        "The provider's error message when the task failed.": "Teachtaireacht earráide an tsoláthraí nuair a theip ar an gcúram.",
        "True when the paper was too long for one task and was summarised part by part.": "Fíor nuair a bhí an páipéar rófhada do chúram amháin agus achoimríodh é cuid ar chuid.",
        "When the clerk last showed or hid the summary.": "Nuair a thaispeáin nó a d'fholaigh an cléireach an achoimre go deireanach.",
        "requested until the AI answers, then draft or failed; a clerk shows a draft to members or hides it.": "iarrtha go dtí go bhfreagraíonn an IS, ansin dréacht nó theip air; taispeánann cléireach dréacht do bhaill nó folaíonn sé é.",
        "AI-generated summary, checked by {name} on {date}": "Achoimre ginte ag IS, seiceáilte ag {name} ar {date}",
        "Asked the AI provider. The summary appears here as a draft when it is ready.": "Iarradh ar an soláthraí IS. Feicfear an achoimre anseo mar dhréacht nuair a bheidh sí réidh.",
        "Compare with": "Cuir i gcomparáid le",
        "Compare {name} with another paper": "Cuir {name} i gcomparáid le páipéar eile",
        "Comparison of {paper} with {other}": "Comparáid idir {paper} agus {other}",
        "Hidden": "I bhfolach",
        "No AI provider is installed, so papers cannot be summarised.": "Níl aon soláthraí IS suiteáilte, mar sin ní féidir páipéir a achoimriú.",
        "No summaries of the papers yet.": "Gan achoimrí ar na páipéir fós.",
        "Requested": "Iarrtha",
        "Show to members": "Taispeáin do bhaill",
        "Shown to members": "Taispeánta do bhaill",
        "Summarise": "Achoimrigh",
        "Summarise {name}": "Achoimrigh {name}",
        "Summary of {paper}": "Achoimre ar {paper}",
        "Summary text": "Téacs na hachoimre",
        "The AI provider could not write it: {reason}": "Níorbh fhéidir leis an soláthraí IS é a scríobh: {reason}",
        "The paper was long, so it was summarised in parts first.": "Bhí an páipéar fada, mar sin achoimríodh ina chodanna é ar dtús.",
        "The summaries of this agenda item could not be read.": "Níorbh fhéidir achoimrí na míre cláir oibre seo a léamh.",
        "The summary could not be asked for.": "Níorbh fhéidir an achoimre a iarraidh.",
        "The summary could not be saved.": "Níorbh fhéidir an achoimre a shábháil.",
        "Waiting for the AI provider. Reload the page in a few minutes.": "Ag fanacht ar an soláthraí IS. Athlódáil an leathanach i gceann cúpla nóiméad.",
        "Summaries of the papers": "Achoimrí na bpáipéar",
        "Meeting broadcast": "Craoladh cruinnithe",
        "A public livestream of a meeting: its status, the player and recording addresses, the broadcast parts and the released captions. Readable without an account once its publication date has passed.": "Sruth beo poiblí de chruinniú: a stádas, seoltaí an tseinnteora agus an taifeadta, codanna an chraolta agus na fotheidil scaoilte. Inléite gan cuntas nuair a bhíonn a dháta foilsithe caite.",
        "The meeting this broadcast shows; one broadcast per meeting.": "An cruinniú a thaispeánann an craoladh seo; craoladh amháin in aghaidh an chruinnithe.",
        "The meeting's title, copied when the broadcast is made, so the public row needs no private meeting.": "Teideal an chruinnithe, cóipeáilte nuair a dhéantar an craoladh, ionas nach dteastaíonn cruinniú príobháideach ón tsraith phoiblí.",
        "The name of the body that meets, copied when the broadcast is made.": "Ainm an chomhlachta a thagann le chéile, cóipeáilte nuair a dhéantar an craoladh.",
        "When the meeting starts, copied when the broadcast is made.": "Nuair a thosaíonn an cruinniú, cóipeáilte nuair a dhéantar an craoladh.",
