        "The Nextcloud group whose members hold this authority, for an authority given to a function rather than a named person. Optional.": "An grúpa Nextcloud a bhfuil an t-údarás seo ag a bhaill, d'údarás a tugadh d'fheidhm seachas do dhuine ainmnithe. Roghnach.",
        "The act keys this authority covers, as the asking app names them (for example a decision type or a case type). An empty list covers no act: the delegated authority check never reads an empty list as 'everything'.": "Eochracha na ngníomhartha a chlúdaíonn an t-údarás seo, mar a ainmníonn an aip a iarrann iad (mar shampla cineál cinnidh nó cineál cáis). Ní chlúdaíonn liosta folamh aon ghníomh: ní léann seiceáil an údaráis tarmligthe liosta folamh mar 'gach rud' riamh.",
